<script lang="ts">
	import { onMount } from 'svelte'; import WorkbenchPage from '$lib/components/dashboard/WorkbenchPage.svelte'; import MetricTile from '$lib/components/dashboard/MetricTile.svelte'; import MultiLine from '$lib/components/dashboard/MultiLine.svelte'; import BarContrib from '$lib/components/dashboard/BarContrib.svelte'; import GaugeRing from '$lib/components/dashboard/GaugeRing.svelte'; import Panel from '$lib/components/dashboard/Panel.svelte'; import { api } from '$lib/services/api';
	let training=$state(false); let status=$state<Record<string,unknown>>({}); let error=$state('');
	onMount(async()=>{try{status=(await api.fl.getStatus()) as Record<string,unknown>}catch(e){error=e instanceof Error?e.message:'FL service unavailable'}});
	async function toggle(){try{if(training)await api.fl.stopTraining();else await api.fl.startTraining({strategy:'qapfl'});training=!training}catch(e){error=e instanceof Error?e.message:'Training action failed'}}
	const rounds=[.71,.75,.78,.8,.82,.84,.855,.869,.878,.884,.891]; const losses=[.71,.56,.43,.35,.3,.27,.24,.22,.2,.19,.18]; const clients=[{name:'client_01',value:.27},{name:'client_02',value:.2},{name:'client_03',value:.16},{name:'client_04',value:.14},{name:'client_05',value:.11},{name:'client_06',value:.07}];
</script>
<svelte:head><title>Federation | NHM</title></svelte:head>
<WorkbenchPage eyebrow="03 / FEDERATION" title="Learn together. Keep data local." description="QAPFL makes signal quality part of the learning loop: local traces stay at the edge while weighted model updates converge into a stronger global signal.">
	<div class="command"><span><i class:active={training}></i> ROUND {String(status.current_round || 11).padStart(2,'0')} / {training?'TRAINING':'READY'}</span><span>MODEL / {String(status.global_model_version || 'qapfl-v0.4')}</span><span>PRIVACY / UPDATES ONLY</span><button class:stop={training} onclick={toggle}>{training?'STOP ROUND':'START ROUND'} ↗</button></div>{#if error}<div class="error">{error}</div>{/if}
	<div class="metrics"><MetricTile label="Active clients" value={String(status.active_clients || 8)} detail="8 SIMULATED WEARABLES" tone="cyan" /><MetricTile label="Global accuracy" value={`${Math.round(Number(status.global_accuracy || .891)*100)}%`} detail="VALIDATION / HELD OUT" trend="+4.8%" values={rounds.map(v=>v*100)} /><MetricTile label="Global F1" value="0.884" detail="QAPFL / ROUND 11" values={rounds.map(v=>(v-.01)*100)} /><MetricTile label="Model updates" value="4.2" unit="MB" detail="RAW DATA / 0 BYTES" tone="amber" /></div>
	<div class="network"><div class="network-title"><span>FEDERATION FLOW / QUALITY-AWARE AGGREGATION</span><small>LOCAL GRADIENTS → GLOBAL MODEL</small></div><div class="flow"><div class="clients"><span style="--delay:0s">ECG / SQI 92</span><span style="--delay:.2s">PPG / SQI 86</span><span style="--delay:.4s">ECG / SQI 78</span><span style="--delay:.6s">PPG / SQI 71</span></div><div class="beams"><i></i><i></i><i></i><i></i></div><div class="core"><b>QAPFL</b><small>QUALITY WEIGHTED</small><strong>GLOBAL MODEL</strong></div></div></div>
	<div class="grid"><Panel eyebrow="CONVERGENCE / 11 ROUNDS" title="Accuracy meets loss" note="QAPFL STRATEGY"><MultiLine series={[{name:'Global accuracy',color:'#2bb8b0',values:rounds.map(v=>v*100)},{name:'Global loss × 100',color:'#fb7185',values:losses.map(v=>v*100)}]} xLabels={['01','03','05','07','09','11']} yMin={0} yMax={100} /></Panel><Panel eyebrow="AGGREGATION / ROUND 11" title="Who moves the model?" note="SOFTMAX WEIGHTS"><div class="aggregation"><BarContrib features={clients} maxAbs={.3} height={208} /><div class="quality-bars"><span>QAPFL weighting</span><i style="--w:78%"></i><span>FedAvg baseline</span><i style="--w:50%"></i></div></div></Panel></div>
	<div class="grid bottom"><Panel eyebrow="PRIVACY / EDGE" title="Raw physiology never leaves the node" note="DATA CONTRACT"><div class="privacy-flow"><div><b>RAW SIGNALS</b><span>ECG · PPG · SpO₂</span></div><strong>×</strong><div><b>LOCAL TRAINING</b><span>features + gradients</span></div><strong>→</strong><div class="safe"><b>MODEL UPDATE</b><span>encrypted / weighted</span></div></div></Panel><Panel eyebrow="CLIENT HEALTH" title="Signal quality shapes participation" note="OVERALL SQI"><div class="rings"><GaugeRing value={84} label="NETWORK SQI" color="#2bb8b0" size={112} /><div><p><b>8 / 8</b> clients connected</p><p><b>0</b> raw samples uploaded</p><p><b>12%</b> quality influence</p></div></div></Panel></div>
</WorkbenchPage>
